		pdfPanel.SetActive(false);
		hasCheckedPPE = false;
		startTrackingRubberMat = false;
		rubberMatCollider.enabled = false;
		mainGuidePanel.SetActive(false);

		statusImg1.SetActive(false);
		statusImg2.SetActive(false);
		statusImg3.SetActive(false);
		statusText1.color = Color.white;
		statusText2.color = Color.white;
		statusText3.color = Color.white;

		eTaskInstructionsResponseWrapper.eTaskInstructionsResponses.Clear();
		newInstruction.Clear();
		equipmentResponseWrapper.equipmentResponse.Clear();

		startTrackingStartingPoint = false;
		guideStartingPoint.SetActive(false);
		guideStartingPointCollider.enabled = false;
	}

	public override void UIInteractable(bool interactableStatus) {
		base.UIInteractable(interactableStatus);
		nextButtonInitialPanel.button.enabled = interactableStatus;
		nextButtonSmallPanel.button.enabled = interactableStatus;
		previousButtonSmallPanel.button.enabled = interactableStatus;
		completeNextButton.button.enabled = interactableStatus;
		showPdfButton.button.enabled = interactableStatus;
		closePdfButton.button.enabled = interactableStatus;
	}

	#region Photo Taking
	void PhotoTaken(ActiveValidations parameters) {
		if (pageManager.managerControlScript.loginScript.playerType != PlayerType.E) return;
		if (currentIndex == 3) {
			string[] imageArray = { samplePhotoGreenLightOff, samplePhotoGreenLightOn, parameters.base64_image };
			ActiveValidationsOpenaiMultiple parametersWithMultipleImages = new ActiveValidationsOpenaiMultiple(
				pageManager.cameraPanel.currentPhotoMessageInput,
				imageArray
			);

			string jsonDataActiveValidation = JsonUtility.ToJson(parametersWithMultipleImages);
			Debug.Log($"EIC, Sending Data To OpenAI on step {currentIndex}: {pageManager.cameraPanel.currentPhotoMessageInput}");
			Debug.Log($"Result Photo: {parameters.base64_image}");
			StartCoroutine(
				ApiManager.instance.APICallPOST(APIPostMiddlePath.APIPostMiddlePathList[(int)APIPostMiddlePathEnum.ActiveValidationsOpenaiMultiple],
				jsonDataActiveValidation,
				() => {
				},
				CheckPhoto
				));
		}
		else if (currentIndex == 4) {
			//string[] imageArray = { samplePhotoPointToNeutral, samplePhotoPointToTrip, parameters.base64_image };
			string[] imageArray = { samplePhotoTripOrNeutral, parameters.base64_image };
			ActiveValidationsOpenaiMultiple parametersWithMultipleImages = new ActiveValidationsOpenaiMultiple(
				pageManager.cameraPanel.currentPhotoMessageInput,
				imageArray
			);

			string jsonDataActiveValidation = JsonUtility.ToJson(parametersWithMultipleImages);
			Debug.Log($"EIC, Sending Data To OpenAI on step {currentIndex}: {pageManager.cameraPanel.currentPhotoMessageInput}");
			Debug.Log($"Result Photo: {parameters.base64_image}");
			StartCoroutine(
				ApiManager.instance.APICallPOST(APIPostMiddlePath.APIPostMiddlePathList[(int)APIPostMiddlePathEnum.ActiveValidationsOpenaiMultiple],
				jsonDataActiveValidation,
				() => {
				},
				CheckPhoto
				));
		}
		else {
			string jsonDataActiveValidation = JsonUtility.ToJson(parameters);
			Debug.Log($"EIC, Sending Data To OpenAI on step {currentIndex}: {jsonDataActiveValidation}");
			Debug.Log($"Result Photo: {parameters.base64_image}");
			StartCoroutine(
				ApiManager.instance.APICallPOST(APIPostMiddlePath.APIPostMiddlePathList[(int)APIPostMiddlePathEnum.ActiveValidationsOpenAi],
				jsonDataActiveValidation,
				() => {
				},
				CheckPhoto
				));
		}
	}

	void CheckPhoto(DownloadHandler returnedItems) {
		Debug.Log($"EIC, Result Received From OpenAI on step {currentIndex}: {returnedItems.text}");
		electricianActiveValidationResponse = JsonUtility.FromJson<ElectricianActiveValidationResponse>(returnedItems.text);
		if (electricianActiveValidationResponse != null) {
			if (CheckCondition(electricianActiveValidationResponse)) {
				AudioManager.instance.audioSource.PlayOneShot(AudioManager.instance.ActiveValidationSuccessSfx);
				StartCoroutine(StartCountdown(5, () => {
					pageManager.cameraPanel.cameraPanel.SetActive(false);
					pageManager.cameraPanel.takePhotoButton.button.enabled = false;
					pageManager.cameraPanel.StopAutoTakePhotoForActiveValidation();
					nextButtonSmallPanel.button.enabled = true;
					previousButtonSmallPanel.button.enabled = true;
					nextStepButtonTextPanel.button.enabled = true;
					nextStepButtonImageTextPanel.button.enabled = true;
					previousStepButtonImageTextPanel.button.enabled = true;
					previousStepButtonTextPanel.button.enabled = true;
					showPdfButton.button.enabled = true;
					closePdfButton.button.enabled = true;
					if (currentIndex == 7) {
						var queryParamsUserID = new Dictionary<string, string> {
						{"jobpack_no", "80771772" },
						{"document_name", "Electrical Isolation Certificate" }
					};
						ApiManager.instance.APICallGETWithParameters(
											APIGetMiddlePath.APIGetMiddlePathList[(int)APIGetMiddlePathEnum.JobpackDocumentSingle],
											queryParamsUserID,
											() => {
												lotoPanel.SetActive(true);
												stepByStepGuidePanelWithImage.SetActive(false);
												stepByStepGuideTextPanel.SetActive(false);
												stepByStepGuidePanelParentObj.SetActive(false);
											},
											AssignPDF
											//ShowPdfFunction
											//DownloadHandler downloadHandler () => {
											//	StartCoroutine(ShowPDF);
											//}
											//AssignPDF
											);
					} else {
						SwitchPanel(1);
					}
				}));
			} else {
				AudioManager.instance.audioSource.PlayOneShot(AudioManager.instance.ActiveValidationFailSfx);
				StartCoroutine(StartCountdown(5, () => {
					pageManager.cameraPanel.AutoTakePhotoForActiveValidation();
				}));
			}
		} else {
			pageManager.aiValidationPanel.aiValidateStatusPanel.SetActive(true);
			AudioManager.instance.audioSource.PlayOneShot(AudioManager.instance.ActiveValidationFailSfx);
			pageManager.aiValidationPanel.aiValidateStatusText.text = "Validation Failed";
			pageManager.aiValidationPanel.aiValidateDetailsText.text = "Invalid Result";
			StartCoroutine(StartCountdown(5, () => {
				pageManager.cameraPanel.AutoTakePhotoForActiveValidation();
			}));
		}
	}

	bool CheckCondition(ElectricianActiveValidationResponse itemToCheck) {
		pageManager.aiValidationPanel.aiValidateStatusPanel.SetActive(true);
		if (currentIndex == 3) {
			if (itemToCheck.motor_stop_light_green.ToLower() == "on" && itemToCheck.is_0_A == true) {
				pageManager.aiValidationPanel.aiValidateStatusText.text = "Validation Successful";
				pageManager.aiValidationPanel.aiValidateDetailsText.text = "Current Motor Stop Light: " + itemToCheck.motor_stop_light_green.ToUpper() + "\n" + "Current AMP reading: " + itemToCheck.is_0_A_Reading.ToUpper();
				motorStatusText.text = itemToCheck.motor_stop_light_green;
				ampMeterText.text = itemToCheck.is_0_A_Reading;
				return true;
			} else {
				pageManager.aiValidationPanel.aiValidateStatusText.text = "Validation Failed";
				pageManager.aiValidationPanel.aiValidateDetailsText.text = "Current Motor Stop Light: " + itemToCheck.motor_stop_light_green.ToUpper() + "\n" + "Current AMP reading: " + itemToCheck.is_0_A_Reading.ToUpper();
				motorStatusText.text = itemToCheck.motor_stop_light_green;
				ampMeterText.text = itemToCheck.is_0_A_Reading;
				return false;
			}
		} else if (currentIndex == 4) {
			if (itemToCheck.horizontal_or_vertical_or_not_detected.ToLower().Contains("vertical")) {
				pageManager.aiValidationPanel.aiValidateStatusText.text = "Validation Successful";
				pageManager.aiValidationPanel.aiValidateDetailsText.text = "Switch Status: Trip";
				return true;
			} else {
				pageManager.aiValidationPanel.aiValidateStatusText.text = "Validation Failed";
				if (itemToCheck.horizontal_or_vertical_or_not_detected.ToLower().Contains("horizontal")){
					pageManager.aiValidationPanel.aiValidateDetailsText.text = "Switch Status: Neutral";
				} else {
					pageManager.aiValidationPanel.aiValidateDetailsText.text = "Switch Status: Not detected";
				}
				return false;
			}
		} else if (currentIndex == 5) {
			if (!itemToCheck.is_0_kV) {
				pageManager.aiValidationPanel.aiValidateStatusText.text = "Validation Failed";
				pageManager.aiValidationPanel.aiValidateDetailsText.text = "Voltage Reading: " + itemToCheck.is_0_kV_Reading.ToUpper();
				return false;
			} else {
				pageManager.aiValidationPanel.aiValidateStatusText.text = "Validation Successful";
				pageManager.aiValidationPanel.aiValidateDetailsText.text = "Voltage Reading: " + itemToCheck.is_0_kV_Reading.ToUpper();
				return true;
			}
		} else if (currentIndex == 7) {
			if (itemToCheck.is_Blue_Card && itemToCheck.is_Red_Card) {
				pageManager.aiValidationPanel.aiValidateStatusText.text = "Validation Successful";
				pageManager.aiValidationPanel.aiValidateDetailsText.text = "Both Red and Blue LOTO Detected";
				statusImg1.SetActive(true);
				statusImg2.SetActive(true);
				statusImg3.SetActive(true);
				statusText1.color = Color.green;
				statusText2.color = Color.green;
				statusText3.color = Color.green;
				return true;
			} else {
				pageManager.aiValidationPanel.aiValidateStatusText.text = "Validation Failed";
				pageManager.aiValidationPanel.aiValidateDetailsText.text = "LOTO Not Detected";
				return false;
			}
		} else {
			return false;
		}
	}
	#endregion

	#region PDF reading
	void LoadPDFDocumentAsync(string url) {
		documentPromise = PDFDocument.LoadDocumentFromUrlAsync(url);
	}

	void OnDocumentLoaded(PDFDocument document) {
		pdfDocument = document;
		int pageCount = pdfDocument.GetPageCount();
		for (int i = 0; i < pageCount; i++) {
			PDFRenderer renderer = new PDFRenderer();
			Texture2D tex = renderer.RenderPageToTexture(pdfDocument.GetPage(i), 1024, 1024);
			tex.filterMode = FilterMode.Bilinear;
			tex.anisoLevel = 8;
			Sprite pageSprite = Sprite.Create(tex, new Rect(0, 0, tex.width, tex.height), Vector2.zero);
			GameObject pageObj = GetPage();
			pageObj.GetComponent<Image>().sprite = pageSprite;
		}
	}

	void OnDocumentLoadFailed() {
		Debug.LogError("Failed to load PDF document.");
	}

	IEnumerator ShowPDF() {
		yield return new WaitForSeconds(5);
		lotoPanel.SetActive(false);
		pdfPanel.SetActive(true);
	}
	void AssignPDF(DownloadHandler returnedItems) {
		string wrappedJson = returnedItems.text;
		JobpackDocumentSingleResponse jobpackDocumentSingleResponse = JsonUtility.FromJson<JobpackDocumentSingleResponse>(wrappedJson);
		LoadPDFDocumentAsync(jobpackDocumentSingleResponse.blob_url);
		StartCoroutine(ShowPDF());
	}
	#endregion
}

[Serializable]
public class ElectricianActiveValidationResponse {
	public bool is_NG3108;
	public string horizontal_or_vertical_or_not_detected;
	public string motor_run_light_red;
	public string motor_stop_light_green;
	public bool is_0_kV;
	public string is_0_kV_Reading;
	public bool is_0_A;
	public string is_0_A_Reading;
	public bool is_Blue_Card;
	public bool is_Red_Card;
}
